# In demo, the right-bottom shape was selected
# What makes it special beyond "lowest min-color"?

demo_right_bottom = [[1,3,3],[1,2,2],[1,3,2]]

# Check if this is the ONLY shape with certain structural properties

test_shapes_grids = {
    'Shape 0': [[3,6,6],[3,3,3],[6,3,6]],
    'Shape 1': [[7,1,7],[1,7,7],[7,1,1]],
    'Shape 2': [[8,8,5],[5,5,5],[5,5,8]],
    'Shape 3': [[9,4,4],[4,4,4],[2,2,2]]
}

def check_first_col_same(grid):
    """Check if first column has all same value"""
    if not grid:
        return False
    first_val = grid[0][0]
    return all(grid[i][0] == first_val for i in range(len(grid)))

def check_last_col_same(grid):
    """Check if last column has all same value"""
    if not grid:
        return False
    last_val = grid[0][-1]
    return all(grid[i][-1] == last_val for i in range(len(grid)))

def check_center_is_mode(grid):
    """Check if center pixel is most frequent color"""
    h = len(grid)
    w = len(grid[0])
    center = grid[h//2][w//2]
    freq = {}
    for row in grid:
        for x in row:
            freq[x] = freq.get(x, 0) + 1
    return freq[center] == max(freq.values())

print("Checking structural properties:")
for name, g in test_shapes_grids.items():
    print(f"\n{name}:")
    print(f"  First col same: {check_first_col_same(g)}")
    print(f"  Last col same: {check_last_col_same(g)}")
    print(f"  Center is mode: {check_center_is_mode(g)}")

# Now check demo shape
print("\n\nDemo Right-Bottom:")
